  ('00000000-0000-4000-8000-000000000101', '[Mentor name]', 'Senior Product Manager', '[Company]', 'product', '[One line on their background and products shipped.]', null, null, true, 1),
  ('00000000-0000-4000-8000-000000000102', '[Mentor name]', 'Product Designer', '[Company]', 'design', '', null, null, true, 2),
