insert into public.courses (id, slug, title, short_title, short_code, category, blurb, description, duration_weeks, format, mode, effort, batch_size, start_date, applications_close, price, emi_from, dubuddy_discount, seats_left, outcomes, syllabus_url, lead_mentor_id, guest_mentors_note, featured, published, sort_order) values
  ('00000000-0000-4000-8000-000000000001', 'product-management', 'Product Management Cohort', 'Product Management', 'PM', 'product', 'Go from user problems to shipped features. Write PRDs, define metrics, and present a product case study to mentors.', 'A 12-week live program for students and freshers who want to become Associate Product Managers. Learn the PM toolkit on weekends and finish with a product case study you can walk interviewers through.', 12, 'Live online, weekends', 'Live · Weekends', '8–10 hrs / week', null, null, null, null, null, null, null, array['Talk to users and turn interviews into clear problem statements', 'Write a PRD and user stories engineers can build from', 'Define success metrics and read a product dashboard', 'Prioritise a roadmap with RICE and trade-off reasoning', 'Wireframe flows and test them with real users', 'Crack product sense, metrics and guesstimate interview rounds']::text[], null, '00000000-0000-4000-8000-000000000101', 'Plus guest sessions from PMs across startups and large tech companies.', true, true, 1),
  ('00000000-0000-4000-8000-000000000002', 'ui-ux-design', 'UI/UX Design Cohort', 'UI/UX Design', 'UX', 'design', 'Research, wireframe and prototype in Figma. Graduate with two case studies for your design portfolio.', 'A 14-week live program to take you from design basics to a portfolio with two end-to-end case studies.', 14, 'Live online, weekends', 'Live · Weekends', '8–10 hrs / week', null, null, null, null, null, null, null, '{}'::text[], null, '00000000-0000-4000-8000-000000000102', '', true, true, 2),
  ('00000000-0000-4000-8000-000000000003', 'data-analytics', 'Data Analytics Cohort', 'Data Analytics', 'DA', 'data', 'Excel, SQL, Python and Power BI on real business datasets. Build dashboards recruiters can click through.', 'A 16-week live program covering the analyst toolkit on real business datasets.', 16, 'Live online, weekends', 'Live · Weekends', '8–10 hrs / week', null, null, null, null, null, null, null, '{}'::text[], null, '00000000-0000-4000-8000-000000000103', '', true, true, 3),
  ('00000000-0000-4000-8000-000000000004', 'business-analyst', 'Business Analyst Cohort', 'Business Analyst', 'BA', 'data', 'Turn data into decisions: requirement docs, process maps, SQL and stakeholder-ready presentations.', 'A 12-week live program on requirements, process mapping, SQL and stakeholder communication.', 12, 'Live online, weekends', 'Live · Weekends', '8–10 hrs / week', null, null, null, null, null, null, null, '{}'::text[], null, null, '', false, true, 4),
  ('00000000-0000-4000-8000-000000000005', 'digital-marketing', 'Digital Marketing Cohort', 'Digital Marketing', 'DM', 'marketing', 'Performance ads, SEO, content and analytics. Run a live campaign with a real budget during the program.', 'A 10-week live program on performance marketing, SEO, content and analytics.', 10, 'Live online, weekends', 'Live · Weekends', '8–10 hrs / week', null, null, null, null, null, null, null, '{}'::text[], null, '00000000-0000-4000-8000-000000000104', '', false, true, 5),
  ('00000000-0000-4000-8000-000000000006', 'applied-generative-ai', 'Applied Generative AI Bootcamp', 'Applied Generative AI', 'AI', 'ai', 'Use AI tools and APIs to automate real work: prompt design, no-code agents and a capstone you can demo.', 'A 6-week live bootcamp on using AI tools and APIs to automate real work.', 6, 'Live online, weekends', 'Live · Weekends', '8–10 hrs / week', null, null, null, null, null, null, null, '{}'::text[], null, null, '', true, true, 6)
insert into public.course_modules (course_id, position, weeks_label, title, topics, assignment) values
  ('00000000-0000-4000-8000-000000000001', 0, 'Week 1–2', 'What PMs actually do', 'The PM role across startups and big tech, product lifecycle, working with design and engineering.', 'Teardown of an app you use daily.'),
  ('00000000-0000-4000-8000-000000000001', 1, 'Week 3–4', 'User research & problem discovery', 'User interviews, personas, jobs-to-be-done, synthesising insights.', 'Run 5 user interviews and present findings.'),
  ('00000000-0000-4000-8000-000000000001', 2, 'Week 5–6', 'Solutioning & PRDs', 'Ideation, prioritisation frameworks, writing PRDs and user stories.', 'Write a PRD for a new feature.'),
  ('00000000-0000-4000-8000-000000000001', 3, 'Week 7–8', 'Design & prototyping for PMs', 'Wireframing in Figma, usability testing, iterating on feedback.', 'Clickable prototype tested with users.'),
  ('00000000-0000-4000-8000-000000000001', 4, 'Week 9–10', 'Metrics, SQL & experimentation', 'North-star metrics, funnels, basic SQL, A/B testing.', 'Metrics plan and dashboard for your feature.'),
  ('00000000-0000-4000-8000-000000000001', 5, 'Week 11–12', 'Capstone & interview prep', 'Roadmapping, stakeholder pitch, resume and mock interviews.', 'Capstone demo day with mentor panel.')
insert into public.course_projects (course_id, position, title, description, accent, image_url) values
  ('00000000-0000-4000-8000-000000000001', 0, 'Product teardown', 'Break down a popular Indian app — users, business model, and what you''d change next.', 'blue', null),
  ('00000000-0000-4000-8000-000000000001', 1, 'Feature PRD & prototype', 'Write a PRD for a new feature and test a clickable prototype with five real users.', 'yellow', null),
  ('00000000-0000-4000-8000-000000000001', 2, 'Capstone case study', 'Pick a problem, define success metrics, and pitch your roadmap to a panel of mentors.', 'green', null)
