insert into public.faqs (id, question, answer, published, sort_order) values
  ('00000000-0000-4000-8000-000000000301', 'Who are these programs for?', 'College students in any year and freshers up to 2 years of experience who want to move into product, design, data, marketing or AI roles. No prior background is needed for most programs.', true, 1),
  ('00000000-0000-4000-8000-000000000302', 'How much time do I need each week?', 'Plan for about 8–10 hours: two live weekend sessions plus assignments. Sessions are recorded in case you miss one.', true, 2),
  ('00000000-0000-4000-8000-000000000303', 'Is this a self-paced course?', 'No. Every program runs as a live cohort with a fixed start date, weekly deadlines and mentor reviews — that structure is what keeps learners finishing.', true, 3),
  ('00000000-0000-4000-8000-000000000304', 'Do you offer placement support?', 'Yes. You get resume and portfolio reviews, mock interviews, and access to internship and job openings shared with the cohort. [Add final placement policy.]', true, 4),
  ('00000000-0000-4000-8000-000000000305', 'Are EMI or scholarships available?', '[Confirm EMI partners and scholarship criteria before launch.]', true, 5),
  ('00000000-0000-4000-8000-000000000306', 'What is the refund policy?', '[Add refund window and conditions before launch.]', true, 6)
